expect(prop(m::MmlMo::defaults().getOwn("symmetric"),Property(false)));
expect(prop(m::MmlMo::defaults().getOwn("maxsize"),Property(h::debugText(units({105,110,102,105,110,105,116,121})))));
expect(prop(m::MmlMo::defaults().getOwn("minsize"),Property(h::debugText(units({48,101,109})))));
